function App() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  const renders = useRef(0);
  renders.current += 1;

  function updateLater() {
    setTimeout(() => {
      setA((x) => x + 1);
      setB((x) => x + 1); // batched with the line above in React 18+
    }, 600);
  }
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>a = {a}, b = {b}</p>
      <p>Render count: {renders.current}</p>
      <button onClick={updateLater}>Update both after 600ms</button>
    </div>
  );
}

// A minimal "resource": read() throws a promise until data is ready
function createResource(fetcher) {
  let status = "pending";
  let result;
  const promise = fetcher().then(
    (v) => { status = "done"; result = v; },
    (e) => { status = "error"; result = e; }
  );
  return {
    read() {
      if (status === "pending") throw promise;
      if (status === "error") throw result;
      return result;
    },
  };
}

const fetchUser = (id) => () =>
  new Promise((resolve) => setTimeout(() => resolve({ id, name: "User " + id }), 700));

function Profile({ resource }) {
  const user = resource.read();   // suspends until ready
  return <p>Hello, <b>{user.name}</b>!</p>;
}

function App() {
  const [id, setId] = useState(1);
  const [resource, setResource] = useState(() => createResource(fetchUser(1)));
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => { const next = id + 1; setId(next); setResource(createResource(fetchUser(next))); }}>
        Load next user
      </button>
      <Suspense fallback={<p>Loading user...</p>}>
        <Profile resource={resource} />
      </Suspense>
    </div>
  );
}

import { use, Suspense } from "react";

// Server Component (or a parent) creates the promise once
export default function Page() {
  const postsPromise = fetch("https://api.example.com/posts").then((r) => r.json());
  return (
    <Suspense fallback={<p>Loading posts...</p>}>
      <Posts postsPromise={postsPromise} />
    </Suspense>
  );
}

"use client";
function Posts({ postsPromise }) {
  const posts = use(postsPromise);
  return (
    <ul>
      {posts.map((p) => <li key={p.id}>{p.title}</li>)}
    </ul>
  );
}

topics.description:
React 19 introduces **Actions**: functions (often async) that perform a mutation and are run inside a **transition**. They give you automatic **pending states**, **error handling**, **optimistic updates** and **sequenced requests**.

### Form actions

`<form action={fn}>` accepts a function. React calls it with `FormData` when the form is submitted, handles `preventDefault` for you, and **resets uncontrolled fields** when the action succeeds.

```jsx
async function addTodo(formData) {
  const title = formData.get("title");
  await api.createTodo(title);
}
<form action={addTodo}>
  <input name="title" />
  <button>Add</button>
</form>
```

Buttons can have their own `formAction`.

### Transitions with async functions

```jsx
const [isPending, startTransition] = useTransition();
startTransition(async () => {
  const error = await updateName(name);
  if (error) setError(error);
});
```

React 19 allows async functions in `startTransition`; `isPending` stays true until the action completes, and the UI stays interactive.

### The related hooks

| Hook | Role |
| --- | --- |
| `useActionState` | state + pending for an action (next topic) |
| `useFormStatus` | read pending state of the parent form from a child |
| `useOptimistic` | show a temporary value during the action |

### Server Actions

In frameworks with Server Components, mark a function with `"use server"` and pass it to `action`. The form works even **before JavaScript loads** (progressive enhancement).

### Why

It replaces the repetitive `onSubmit` + `preventDefault` + `isLoading` + `error` + reset boilerplate with a convention that composes with Suspense and error boundaries.

examples.code:
// React 19
function AddTodo({ onAdd }) {
  async function action(formData) {
    const title = formData.get("title");
    await onAdd(title);          // async work
  }
  return (
    <form action={action}>
      <input name="title" placeholder="New todo" required />
      <button type="submit">Add</button>
    </form>
  );
}

// Equivalent React 18 code needs onSubmit, preventDefault, FormData,
// loading state, error state and manual reset.

topics.description:
### useActionState

```jsx
const [state, formAction, isPending] = useActionState(actionFn, initialState);
```

- `actionFn(previousState, formData)` runs on submit and **returns the new state** (like a reducer with async support).
- `state` is the latest returned value (an error message, a success flag, validated data).
- `formAction` is what you pass to `<form action>`.
- `isPending` is true while running.

```jsx
async function subscribe(prev, formData) {
  const email = formData.get("email");
  if (!email.includes("@")) return { error: "Invalid email" };
  await api.subscribe(email);
  return { ok: true };
}
const [state, action, pending] = useActionState(subscribe, { ok: false });
```

It was called `useFormState` in canary and lives in `react` (not `react-dom`).

### useFormStatus

From `react-dom`. A component **inside** a `<form>` can read the form's status without props:

```jsx
function SubmitButton() {
  const { pending, data, method } = useFormStatus();
  return <button disabled={pending}>{pending ? "Saving..." : "Save"}</button>;
}
```

It must be rendered **inside** the form (a child), not in the same component that renders the `<form>`.

### Design system use

Reusable `<SubmitButton />` and `<Input />` components that know about pending state without prop drilling.

### Combining

`useActionState` for the result and validation messages, `useFormStatus` for deep child components, and `useOptimistic` for instant feedback.

### Tips

Return serializable state from actions; keep the initial state shape the same as returned shapes; return field values to repopulate inputs on error since uncontrolled forms reset.

examples.code:
import { useActionState } from "react";
import { useFormStatus } from "react-dom";

async function subscribeAction(prevState, formData) {
  const email = String(formData.get("email") ?? "");
  if (!email.includes("@")) {
    return { ok: false, error: "Please enter a valid email", email };
  }
  await new Promise((r) => setTimeout(r, 800));   // pretend API
  return { ok: true, error: null, email: "" };
}

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? "Subscribing..." : "Subscribe"}</button>;
}

export default function Newsletter() {
  const [state, formAction, isPending] = useActionState(subscribeAction, { ok: false, error: null, email: "" });
  return (
    <form action={formAction}>
      <input name="email" defaultValue={state.email} aria-invalid={!!state.error} />
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
      {state.ok && <p>Thanks for subscribing!</p>}
    </form>
  );
}

topics.description:
`useOptimistic` implements the optimistic update pattern with almost no code.

```jsx
const [optimisticState, addOptimistic] = useOptimistic(state, updateFn?);
```

- `state` is the real, confirmed value (from props, server or state).
- `addOptimistic(value)` immediately produces a temporary value shown while an Action is in progress.
- Once the Action completes (success or failure) React **discards the optimistic value** and renders the real `state` again. On success the real state has already been updated, on failure the UI reverts automatically.

### Example flow (chat)

```jsx
function Thread({ messages, sendMessage }) {
  const [optimistic, addOptimistic] = useOptimistic(
    messages,
    (current, text) => [...current, { id: crypto.randomUUID(), text, sending: true }]
  );

  async function action(formData) {
    const text = formData.get("text");
    addOptimistic(text);              // shows instantly
    await sendMessage(text);          // updates real `messages` when done
  }
  ...
}
```

### Rules

- `addOptimistic` must be called **inside an Action** (a form action or `startTransition`).
- The reducer function (2nd argument) must be pure.
- Mark optimistic items (`sending: true`) so you can style them (gray, spinner).
- The real state must be updated by your action; `useOptimistic` only layers a temporary view above it.

### Compared with manual rollback

No snapshots, no try/catch to restore. React handles reverting. For cache-based apps TanStack Query's `onMutate` pattern is still common.

examples.code:
import { useOptimistic, useState, useRef } from "react";

export default function Todos() {
  const [todos, setTodos] = useState([{ id: 1, text: "Learn React 19" }]);
  const formRef = useRef(null);

  const [optimisticTodos, addOptimistic] = useOptimistic(todos, (current, text) => [
    ...current,
    { id: "temp-" + text, text, pending: true },
  ]);

  async function add(formData) {
    const text = formData.get("text");
    addOptimistic(text);
    formRef.current?.reset();
    const saved = await fakeSave(text);            // 1s later
    setTodos((t) => [...t, saved]);                // real state
  }

  return (
    <>
      <ul>
        {optimisticTodos.map((t) => (
          <li key={t.id} style={{ opacity: t.pending ? 0.5 : 1 }}>{t.text}</li>
        ))}
      </ul>
      <form ref={formRef} action={add}>
        <input name="text" />
        <button>Add</button>
      </form>
    </>
  );
}

import { createContext, useContext } from "react";

const ThemeContext = createContext("light");

function FancyInput({ ref, ...props }) {      // ref is just a prop
  return <input ref={ref} {...props} />;
}

function Page() {
  return (
    <ThemeContext value="dark">                {/* no .Provider */}
      <title>My Page</title>                   {/* hoisted to <head> */}
      <meta name="description" content="React 19 demo" />
      <Content />
    </ThemeContext>
  );
}

function Content() {
  const theme = useContext(ThemeContext);
  return <FancyInput ref={(node) => { node?.focus(); return () => console.log("cleanup"); }} placeholder={theme} />;
}

